// Status code
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

// Response time
pm.test("Response time is less than 1000ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(1000);
});

// Response is an array
pm.test("Response is an array", function () {
    const response = pm.response.json();
    pm.expect(response).to.be.an("array");
});

// Array is not empty
pm.test("Products array is not empty", function () {
    const response = pm.response.json();
    pm.expect(response.length).to.be.above(0);
});

// Each product has required fields
pm.test("Each product has required fields", function () {
    const products = pm.response.json();

    products.forEach(function (product) {
        pm.expect(product).to.have.property("id");
        pm.expect(product).to.have.property("title");
        pm.expect(product).to.have.property("price");
        pm.expect(product).to.have.property("description");
        pm.expect(product).to.have.property("category");
        pm.expect(product).to.have.property("image");
    });
});

const res = pm.response.json();
const requestBody = pm.request.body.raw ? JSON.parse(pm.request.body.raw) : {};

// ========== POSITIVE ==========
pm.test("Status code is 200 or 201", () => {
    pm.expect(pm.response.code).to.be.oneOf([200, 201]);
});

pm.test("Response contains an ID", () => {
    pm.expect(res).to.have.property("id");
});

pm.test("Title matches request body", () => {
    if (requestBody.title) {
        pm.expect(res.title).to.eql(requestBody.title);
    }
});

// ========== NEGATIVE ==========

// Case 1: Empty body
pm.test("Negative - Empty body should not create valid product", () => {
    if (!pm.request.body.raw || pm.request.body.raw.trim() === "{}") {
        pm.expect(res).to.not.have.property("title");
    }
});

// Case 2: Missing title
pm.test("Negative - Missing title", () => {
    if (requestBody && !requestBody.title) {
        // API still returns 200, so we check that title is missing/undefined
        pm.expect(res.title).to.be.undefined;
    }
});

// Case 3: Invalid price type
pm.test("Negative - Price should be a number", () => {
    if (requestBody.price && typeof requestBody.price === "string") {
        // API may still accept it, but we document the bad behavior
        console.log("Warning: API accepted string as price");
    }
});

